const executionId=String($execution?.id??"manual");
const definitions=[
 {testId:"A01",name:"Graduate count numeric integrity",kind:"numeric_count",chatInput:"فقط عدد: تعداد کل فارغ‌التحصیلان دانشگاه چند نفر است؟",expectedCount:30},
 {testId:"A02",name:"Course C002 retrieval",kind:"course_lookup",chatInput:"نام درس با شناسه C002 چیست؟",expectedCourseId:"C002",expectedCourseName:"ساختمان داده"},
 {testId:"A03",name:"Independent multi-plan analysis",kind:"multi_plan",chatInput:"تعداد کل فارغ‌التحصیلان دانشگاه را گزارش کن و به‌صورت مستقل پنج مهارت با بیشترین شکاف مهارتی بازار را نیز رتبه‌بندی کن.",expectedCount:30},
 {testId:"A04",name:"Out-of-domain rejection",kind:"out_of_scope",chatInput:"قیمت روز بیت‌کوین چقدر است؟"}
];
return definitions.map(test=>{
 const sessionId="nexusops-e2e-"+executionId+"-"+test.testId;
 return {json:{...test,sessionId,requestBody:{action:"sendMessage",sessionId,chatInput:test.chatInput}}};
});

function parseBody(value){
 if(value&&typeof value==="object")return value;
 const source=String(value??"").trim();
 if(!source)return null;
 try{return JSON.parse(source)}catch{return {output:source}}
}
function normalizeDigits(value){
 return String(value??"").replace(/[۰-۹]/g,d=>"۰۱۲۳۴۵۶۷۸۹".indexOf(d)).replace(/[٠-٩]/g,d=>"٠١٢٣٤٥٦٧٨٩".indexOf(d));
}
function responseText(body){
 if(Array.isArray(body))body=body[0];
 if(typeof body==="string")return body;
 if(!body||typeof body!=="object")return String(body??"");
 for(const key of ["output","text","message"])if(typeof body[key]==="string")return body[key];
 if(body.data&&typeof body.data==="object")return responseText(body.data);
 return JSON.stringify(body);
}
const cases=$("Build Agent Test Cases").all().map(x=>x.json);
const items=$input.all();
const responsesAligned=items.length===cases.length;
const results=[];
for(let i=0;i<cases.length;i++){
 const test=cases[i],entry=responsesAligned?items[i]:null;
 const response=entry?.json??{},body=parseBody(response.body??response.data),text=responseText(body),normalized=normalizeDigits(text);
 const statusCode=Number(response.statusCode??0);
 let passed=false,detail="";
 if(!entry)detail="Response correlation failed: serial loop output count does not match the case count.";
 else if(response.error)detail="Transport error: "+String(response.error.message??response.error).slice(0,500);
 else if(statusCode&& (statusCode<200||statusCode>=300))detail="Chat Trigger returned HTTP "+statusCode+": "+text.slice(0,500);
 else if(!text.trim())detail="Chat Trigger returned an empty response.";
 else if(test.kind==="numeric_count"){
  passed=new RegExp("(?:^|\\D)"+test.expectedCount+"(?:\\D|$)").test(normalized);
  detail=passed?"Expected graduate count "+test.expectedCount+" appears in the actual Agent response.":"Expected exact count token "+test.expectedCount+" was not found: "+text.slice(0,700);
 }else if(test.kind==="course_lookup"){
  passed=text.includes(test.expectedCourseId)&&text.includes(test.expectedCourseName);
  detail=passed?"Course identifier and expected Persian course name are present.":"Expected course identifier/name not both present: "+text.slice(0,700);
 }else if(test.kind==="multi_plan"){
  const hasCount=new RegExp("(?:^|\\D)"+test.expectedCount+"(?:\\D|$)").test(normalized);
  const hasGap=/شکاف مهارتی|شکاف بازار/.test(text);
  const hasFailure=/partial_failure|incomplete|وضعیت اجرای چندبرنامه‌ای.*(?:partial_failure|incomplete|unknown)/i.test(text);
  passed=hasCount&&hasGap&&!hasFailure;
  detail=passed?"The response contains the graduate-count evidence and a separate skill-gap result without an explicit incomplete/partial-failure warning.":"Multi-objective response did not satisfy all text-level assertions: "+text.slice(0,1000);
 }else if(test.kind==="out_of_scope"){
  passed=/محدوده/.test(text)&&/دانشگاهی|بازار کار/.test(text);
  detail=passed?"Out-of-domain request was rejected by the domain gate.":"Expected domain rejection was not found: "+text.slice(0,700);
 }
 results.push({testId:test.testId,name:test.name,status:passed?"PASS":"FAIL",httpStatus:statusCode||null,detail});
}
const passed=results.filter(x=>x.status==="PASS").length,failed=results.length-passed;
return [{json:{suite:"NexusOps Agentic E2E Acceptance Suite",executedAt:new Date().toISOString(),summary:{total:results.length,passed,failed,overall:failed===0&&responsesAligned?"PASS":"FAIL"},results,scope:"Exercises the active n8n Chat Trigger, local Ollama planner/answer writer, MCP, Elasticsearch and final response path. It does not inject MCP faults or claim concurrency coverage."}}];
